let (round, gap) = (5u64, 3u64);
// (name, last_seen, kind_rank, added)
let bank = [
    ("a", Some(2u64), 0, 1),
    ("b", Some(1), 1, 2),
    ("c", Some(4), 0, 3),
];
let pick = bank
    .iter()
    .filter(|q| q.1.is_none_or(|s| round - s >= gap))
    .min_by_key(|q| (q.1, q.2, q.3))
    .map(|q| q.0);
println!("{pick:?}");

pub fn revise(&mut self, question: &Question) {
    if !Self::bankable(question) {
        self.retire();
        return;
    }
    let mut question = question.clone();
    question.banked = None;
    self.id = Self::id_of(&question);
    self.question = question;
    self.version += 1;
}
